/* ============ GENERADOR DE SIMULACROS (sección 11) ============ */
(function () {
  'use strict';
  if (typeof document === 'undefined') return;
  const SUBJ = 'fiuba-analisis-matematico-2-parcial';
  const MINUTOS = 180;
  const K_ACTUAL = 'fam2p-sim-actual', K_HIST = 'fam2p-sim-historial', K_REALES = 'fam2p-sim-reales', K_PUNT = 'fam2p-sim-puntajes', K_CRONO = 'fam2p-sim-crono';
  // Bloque del banco: nombre y destino del procedimiento en esta guía.
  const TIPOS = {
    A: ["Dominio, topología y conjuntos de nivel", 'fam2p-s2', 'sección 2'],
    H: ["Extremos libres", 'fam2p-s3', 'sección 3'],
    F: ["Función implícita", 'fam2p-s4', 'sección 4'],
    E: ["Regla de la cadena y composición", 'fam2p-s5', 'sección 5'],
    D: ["Plano tangente, recta normal y aproximación lineal", 'fam2p-s6', 'sección 6'],
    B: ["Curvas: recta tangente y plano normal", 'fam2p-s7', 'sección 7'],
    C: ["Límite, continuidad y diferenciabilidad", 'fam2p-s8', 'sección 8'],
    I: ["Extremos condicionados y absolutos", 'fam2p-s9', 'sección 9'],
  };
  // Ejercicios que la cátedra repitió en dos fechas (mismo enunciado, o el mismo con el vector
  // cambiado de signo): cuentan como uno solo para no repetir. Los idénticos se detectan solos.
  const GEMELOS = [];
  const DESDE_ANIO = 2025; // "cualquier orden real": desde el régimen nuevo
  const ESQ_DEF = ["AHFED"];
  const RE_CAB = /^<b>TIPO ([A-U]) · (.+?) · Ej (\d)\.<\/b>\s*/;
  const ROM = { I: 1, II: 2, III: 3, IV: 4, V: 5, VI: 6, VII: 7, VIII: 8, IX: 9, X: 10, XI: 11, XII: 12 };

  const leer = (k, def) => { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : def; } catch (e) { return def; } };
  const leerLista = (k) => { const v = leer(k, []); return Array.isArray(v) ? v.filter((x) => x !== null && x !== undefined) : []; };
  const guardar = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };
  const mezclar = (arr) => {
    const a = arr.slice();
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
    return a;
  };
  const dos = (n) => (n < 10 ? '0' : '') + n;
  const conId = (id) => document.getElementById(id);

  // ---------- el banco, leído de la sección 10 ----------
  const BANCO = [];      // {id, n, tipo, examen, ej, grupo, enun, ans, resol} (la resolución va en resol)
  const porId = new Map();
  const EXAMENES = [];   // fechas completas, de la más nueva a la más vieja: {clave, f, cuatri, ids, esq}
  const RANGO = {};      // tipo -> [primer n, último n]

  function fechaDe(clave) {
    const m = clave.match(/^(\d{1,2})\/([IVX]+|\d{1,2})\/(\d{2})\b/);
    if (!m) return null;
    const mes = /^\d+$/.test(m[2]) ? +m[2] : ROM[m[2]];
    if (!mes) return null;
    const hs = clave.match(/(\d{1,2}) hs/);
    return { d: +m[1], m: mes, y: 2000 + +m[3], h: hs ? +hs[1] : 0 };
  }
  // Febrero es recuperatorio del segundo cuatrimestre anterior; de marzo a agosto, primero.
  const cuatri = (f) => (f.m <= 2 || (f.m === 3 && f.d <= 15) ? '2C' + (f.y - 1) : f.m <= 8 ? '1C' + f.y : '2C' + f.y);
  const valorFecha = (f) => ((f.y * 100 + f.m) * 100 + f.d) * 100 + f.h;
  const textoPlano = (h) => h.replace(/<[^>]+>/g, '').replace(/[·\s]/g, '').toLowerCase();

  function cargarBanco() {
    if (BANCO.length) return true;
    const lista = (window.RV || {})[SUBJ + '-10'];
    if (!Array.isArray(lista)) return false;
    const grupos = new Map(), porTexto = new Map();
    lista.forEach((q, i) => {
      const m = RE_CAB.exec(q.st || '');
      if (!m) { console.warn('Generador: el 10.' + (i + 1) + ' no tiene la cabecera TIPO · examen · Ej'); return; }
      const e = { id: m[2] + '|' + m[3], n: i + 1, tipo: m[1], examen: m[2], ej: +m[3], enun: q.st.replace(RE_CAB, ''), ans: q.ans || '', resol: q.sol || '' };
      if (porId.has(e.id)) { console.warn('Generador: repetido ' + e.id); return; }
      const t = textoPlano(e.enun);
      e.grupo = porTexto.has(t) ? porTexto.get(t) : e.id;
      if (!porTexto.has(t)) porTexto.set(t, e.id);
      BANCO.push(e);
      porId.set(e.id, e);
      const r = RANGO[e.tipo] = RANGO[e.tipo] || [e.n, e.n];
      r[0] = Math.min(r[0], e.n); r[1] = Math.max(r[1], e.n);
      if (!grupos.has(e.examen)) grupos.set(e.examen, []);
      grupos.get(e.examen).push(e);
    });
    GEMELOS.forEach((par) => { const a = porId.get(par[0]), b = porId.get(par[1]); if (a && b) b.grupo = a.grupo; });
    grupos.forEach((es, clave) => {
      const f = fechaDe(clave);
      // Sólo las fechas con encabezado y con los cinco ejercicios, del 1 al 5.
      if (!f || es.map((e) => e.ej).sort().join('') !== '12345') return;
      es.sort((a, b) => a.ej - b.ej);
      EXAMENES.push({ clave: clave, f: f, cuatri: cuatri(f), ids: es.map((e) => e.id), esq: es.map((e) => e.tipo).join('') });
    });
    EXAMENES.sort((a, b) => valorFecha(b.f) - valorFecha(a.f));
    return BANCO.length > 0;
  }

  // ---------- armado ----------
  // El orden pedido, uno real del régimen nuevo, o uno de los más repetidos (ESQ_DEF).
  function esqueletoPara(opcion) {
    if (/^[A-U]{5}$/.test(opcion)) return opcion;
    if (opcion === 'real') {
      const l = EXAMENES.filter((x) => x.f.y >= DESDE_ANIO);
      if (l.length) return mezclar(l)[0].esq;
    }
    return mezclar(ESQ_DEF)[0];
  }

  // Un ejercicio por posición, del tipo que pide el orden. Nunca dos del mismo examen ni dos
  // gemelos, y se evitan los de los simulacros recientes mientras haya otros.
  function armarNuevo(esq, recientes) {
    const rec = new Set((recientes || []).map((id) => (porId.get(id) || { grupo: id }).grupo));
    const ids = [], examenes = new Set(), usados = new Set();
    for (let k = 0; k < esq.length; k++) {
      const cand = BANCO.filter((e) => e.tipo === esq[k] && !usados.has(e.grupo));
      const otroExamen = cand.filter((e) => !examenes.has(e.examen));
      const nuevos = otroExamen.filter((e) => !rec.has(e.grupo));
      const lista = nuevos.length ? nuevos : otroExamen.length ? otroExamen : cand;
      if (!lista.length) { console.warn('Generador: no hay ejercicios del tipo ' + esq[k]); return null; }
      const e = mezclar(lista)[0];
      ids.push(e.id);
      examenes.add(e.examen);
      usados.add(e.grupo);
    }
    return ids;
  }

  // Una fecha real: la elegida, o una al azar entre las que todavía no se hicieron. Cuando ya
  // se hicieron todas, empieza otra vuelta (sin repetir la última).
  function elegirReal(clave, ultima) {
    if (clave) return EXAMENES.filter((x) => x.clave === clave)[0] || null;
    const hechas = new Set(leerLista(K_REALES));
    let lista = EXAMENES.filter((x) => !hechas.has(x.clave) && x.clave !== ultima);
    if (!lista.length) {
      guardar(K_REALES, []);
      lista = EXAMENES.filter((x) => x.clave !== ultima);
    }
    return lista.length ? mezclar(lista)[0] : EXAMENES[0] || null;
  }

  // ---------- estado ----------
  let sim = null;        // el parcial en pantalla
  let tic = null;        // intervalo del cronómetro
  let pastilla = null;   // el cronómetro fijo abajo a la derecha
  let volver = null;     // botón "Volver al parcial", abajo a la izquierda
  let volverA = null;    // ejercicio o resultado desde el que se fue a otra sección
  const confirma = {};   // primer toque pendiente, por botón

  const persistir = () => { if (sim) guardar(K_ACTUAL, sim); };
  const marcadas = () => sim.ids.filter((id) => sim.marcas[id] !== undefined).length;
  const bien = () => sim.ids.filter((id) => sim.marcas[id] === true).length;
  const valido = (s) => !!s && s.v === 1 && Array.isArray(s.ids) && s.ids.length === 5 && s.ids.every((id) => porId.has(id)) && !!s.vistos && typeof s.vistos === 'object' && !!s.marcas && typeof s.marcas === 'object' && (s.fase === 'resolviendo' || s.fase === 'corrigiendo');

  // Si otra pestaña (u otra copia de esta, restaurada con Atrás) guardó algo distinto, se toma
  // eso y se repinta. Devuelve true si cambió, y entonces el toque que se estaba procesando no
  // se aplica: era sobre un parcial que ya no es el vigente.
  function adoptarGuardado() {
    const g = leer(K_ACTUAL, null);
    if (!valido(g) || (sim && JSON.stringify(g) === JSON.stringify(sim))) return false;
    sim = g;
    pararTic();
    pintarSimulacro();
    if (sim.fase === 'resolviendo' && sim.fin) arrancarCrono(); else pararCrono();
    return true;
  }

  // Un botón que pide un segundo toque antes de hacer algo que no se deshace. El segundo toque
  // cuenta recién después de 0,6 s, así un doble toque sin querer no confirma solo.
  function pedirConfirmacion(btn, clave, texto) {
    const dt = confirma[clave] ? Date.now() - confirma[clave] : Infinity;
    if (dt >= 600 && dt < 5000) { confirma[clave] = 0; avisar(''); return true; }
    if (dt < 600) return false;
    confirma[clave] = Date.now();
    btn.dataset.original = btn.dataset.original || btn.textContent;
    btn.textContent = texto;
    btn.classList.add('sim-confirmar');
    avisar(texto);
    setTimeout(() => { if (confirma[clave] && Date.now() - confirma[clave] >= 4900) { confirma[clave] = 0; restaurarBoton(btn); } }, 5000);
    return false;
  }
  function restaurarBoton(btn) {
    if (!btn) return;
    if (btn.dataset.original) { btn.textContent = btn.dataset.original; delete btn.dataset.original; }
    btn.classList.remove('sim-confirmar');
    avisar('');
  }
  function avisar(t) { const a = conId('fam2p-sim-aviso'); if (a) a.textContent = t; }

  // ---------- pintar ----------
  function pintarPanel() {
    const btn = conId('fam2p-sim-generar');
    confirma.gen = 0;
    if (btn) { delete btn.dataset.original; btn.classList.remove('sim-confirmar'); btn.textContent = sim ? 'Generar otro' : 'Generar parcial'; }
    const h = conId('fam2p-sim-hist');
    if (h) {
      const p = leerLista(K_PUNT).filter((x) => typeof x.p === 'number');
      const hechas = leerLista(K_REALES).filter((c) => EXAMENES.some((x) => x.clave === c)).length;
      let t = p.length
        ? 'Tus últimos parciales: ' + p.map((x) => x.p + '/5').join(', ') + (p.length > 1 ? ' (el más reciente, al final).' : '.')
        : 'Todavía no corregiste ningún parcial en este navegador.';
      if (hechas) t += ' Fechas reales que ya hiciste: ' + hechas + ' de ' + EXAMENES.length + '.';
      h.textContent = t;
    }
    pintarEstado();
  }

  // Al lado del título de la sección 11: el parcial en curso manda sobre el último resultado.
  function pintarEstado() {
    const s = conId('fam2p-sim-estado');
    if (!s) return;
    const ult = leerLista(K_PUNT).filter((x) => typeof x.p === 'number').slice(-1)[0];
    if (sim && sim.fase === 'resolviendo') s.textContent = 'parcial en curso';
    else if (sim && marcadas() < 5) s.textContent = 'corrigiendo: ' + marcadas() + ' de 5';
    else if (ult) s.textContent = 'último parcial: ' + ult.p + '/5';
    else s.textContent = '';
  }

  function pintarModo() {
    const r = document.querySelector('input[name="fam2p-sim-modo"]:checked');
    const real = !!r && r.value === 'real';
    const cn = conId('fam2p-sim-campo-nuevo'), cr = conId('fam2p-sim-campo-real');
    if (cn) cn.hidden = real;
    if (cr) cr.hidden = !real;
    document.querySelectorAll('input[name="fam2p-sim-modo"]').forEach((x) => x.closest('.sim-modo').classList.toggle('sim-modo-on', x.checked));
  }

  function titulo() {
    const corr = sim.fase === 'corrigiendo';
    if (sim.modo === 'real') return sim.azar && !corr ? 'Parcial real (la fecha se muestra al corregir)' : 'Parcial real del ' + sim.fecha;
    return 'Parcial nuevo' + (corr || sim.esqElegido ? ', con el orden ' + sim.esq : '');
  }

  const enlace = (t) => '<a href="#' + TIPOS[t][1] + '">' + TIPOS[t][2] + '</a>';

  function origen(e) {
    const ex = /^parcial sin encabezado/.test(e.examen) ? 'de un ' + e.examen : 'del parcial del ' + e.examen;
    return 'Es el Ej ' + e.ej + ' ' + ex + '; en el banco de la sección 10, el <b>10.' + e.n + '</b>. El procedimiento de este tipo está en la ' + enlace(e.tipo) + '.';
  }

  function pintarSimulacro() {
    const out = conId('fam2p-sim-out');
    if (!out) return;
    Object.keys(confirma).forEach((k) => { confirma[k] = 0; });
    avisar('');
    const f = new Date(sim.creado);
    const corr = sim.fase === 'corrigiendo';
    let h = '<div class="sim-cab" id="fam2p-sim-cab" tabindex="-1"><b>' + titulo() + '</b>, armado el ' + f.getDate() + '/' + (f.getMonth() + 1) + ' a las ' + dos(f.getHours()) + ':' + dos(f.getMinutes()) + '. ';
    if (corr) {
      if (sim.porTiempo) h += '<b>Se terminaron las 3 horas.</b> ';
      h += 'Abrí la resolución de cada uno, comparala con lo tuyo y marcá si te salió. Contá como bien sólo lo que quedó <b>cerrado y con la respuesta escrita</b>: la cátedra cuenta problemas bien resueltos, no planteos.';
    } else {
      h += 'Resolvelo en papel, a libro cerrado, justificando cada paso como pide la cátedra. El tipo de cada ejercicio y las resoluciones aparecen cuando toques <b>Terminé</b>.';
    }
    h += '</div>';
    h += '<div class="sim-hoja"><div class="sim-hoja-t">Análisis Matemático II (CB001) · Primer parcial</div>';
    h += '<div class="sim-hoja-s">5 problemas · 3 horas · se aprueba con 3 bien resueltos</div></div>';
    sim.ids.forEach((id, k) => {
      const e = porId.get(id);
      h += '<div class="rev-ex sim-e" data-k="' + k + '"><div class="qex-h"><span class="qex-n">Ej ' + (k + 1) + '</span>';
      if (corr) h += '<span class="sim-tag">Tipo ' + e.tipo + ' · ' + TIPOS[e.tipo][0] + '</span>';
      h += '</div><div class="qex-st">' + e.enun + '</div>';
      if (corr) {
        h += '<button type="button" class="rev-btn sim-ver">Ver la resolución</button>';
        h += '<div class="rev-body"><div class="rev-ans"><b>Respuesta:</b> ' + e.ans + '</div>';
        if (e.resol) h += '<div class="rev-sol">' + e.resol + '</div>';
        h += '<div class="sim-fuente">' + origen(e) + '</div></div>';
        h += '<div class="sim-marcas" role="group" aria-label="¿Te salió el Ej ' + (k + 1) + '?">';
        h += '<button type="button" class="sim-marca sim-marca-si" data-v="1" aria-pressed="false" disabled>Me salió bien</button>';
        h += '<button type="button" class="sim-marca sim-marca-no" data-v="0" aria-pressed="false" disabled>No me salió</button></div>';
        h += '<div class="sim-marca-nota">Se habilita al abrir la resolución.</div>';
      }
      h += '</div>';
    });
    h += '<div class="sim-pie"><div class="sim-progreso" id="fam2p-sim-prog"></div>';
    if (!corr) h += '<button type="button" class="sim-btn" id="fam2p-sim-terminar">Terminé: ver las resoluciones</button>';
    h += '</div><div class="sim-res" id="fam2p-sim-res" aria-live="polite"></div>';
    out.innerHTML = h;
    if (corr) {
      out.querySelectorAll('.sim-e').forEach((box) => {
        const id = sim.ids[+box.dataset.k];
        if (sim.vistos[id]) abrir(box);
        if (sim.marcas[id] !== undefined) marcar(box, sim.marcas[id]);
      });
    }
    pintarProgreso();
    pintarPanel();
    if (corr) pintarResultado(false);
  }

  function abrir(box) {
    box.classList.add('revealed');
    const b = box.querySelector('.sim-ver');
    if (b) { b.textContent = 'Resolución abierta'; b.disabled = true; }
    box.querySelectorAll('.sim-marca').forEach((m) => { m.disabled = false; });
  }

  function marcar(box, v) {
    box.querySelectorAll('.sim-marca').forEach((m) => { m.setAttribute('aria-pressed', (m.dataset.v === '1') === v ? 'true' : 'false'); });
  }

  function pintarProgreso() {
    pintarEstado();
    const el = conId('fam2p-sim-prog');
    if (!el) return;
    if (sim.fase === 'resolviendo') {
      el.textContent = sim.fin ? 'Con cronómetro de 3 horas.' : sim.resto ? 'Cronómetro en pausa.' : 'Cuando termines, tocá el botón.';
      return;
    }
    const m = marcadas();
    el.textContent = m < 5 ? 'Corregiste ' + m + ' de 5.' : 'Corregido: ' + bien() + ' de 5 bien.';
  }

  function pintarResultado(desplazar) {
    const res = conId('fam2p-sim-res');
    if (!res) return;
    if (marcadas() < 5) { res.innerHTML = ''; return; }
    const b = bien();
    let caja = 'key', t = 'ky-t', lectura;
    if (b === 5) lectura = '<b>Estás, con margen.</b> Probá con otro orden o con una fecha real que no hayas hecho.';
    else if (b === 4) lectura = '<b>Estás.</b> Repasá sólo el que falló y hacé tres más de ese tipo en el banco.';
    else if (b === 3) { caja = 'example'; t = 'ex-t'; lectura = '<b>Aprobás, pero sin margen</b>: cualquier variante que no hayas visto te deja en 2. Hacé seis seguidos del banco de cada tipo que fallaste.'; }
    else { caja = 'trap'; t = 'tr-t'; lectura = '<b>Con esto no aprobás.</b> Antes de volver al banco, releé paso por paso el procedimiento de cada tipo que fallaste: con 2 o menos, lo que falla es el método y no la práctica.'; }
    let r = '<div class="' + caja + ' sim-caja" id="fam2p-sim-resultado" tabindex="-1"><div class="' + t + '">Resultado: ' + b + ' de 5 bien resueltos</div>';
    r += '<p>' + lectura + '</p>';
    const mal = [];
    sim.ids.forEach((id, k) => { if (sim.marcas[id] === false) mal.push([porId.get(id), k]); });
    if (mal.length) {
      r += '<ul class="sim-clases">';
      mal.forEach((x) => {
        const e = x[0], rg = RANGO[e.tipo], cuantos = rg[1] - rg[0] + 1;
        const n = b >= 4 ? 3 : 6;
        const hacer = cuantos > n ? (n === 3 ? 'tres más' : 'seis seguidos') : 'los ' + cuantos;
        r += '<li><b>Ej ' + (x[1] + 1) + '</b>, ' + TIPOS[e.tipo][0].toLowerCase() + ': releé la ' + enlace(e.tipo) + ' y hacé ' + hacer + ' del bloque ' + e.tipo + ' del banco (10.' + rg[0] + ' a 10.' + rg[1] + ').</li>';
      });
      r += '</ul>';
    }
    r += '<p>El orden de este parcial fue <b>' + sim.esq + '</b>.';
    if (b < 5) r += ' Y mirá en qué paso fallaste, no sólo cuántos: si los errores son del último paso (verificar una hipótesis, el signo de una normal, un límite de integración), lo que falta es el chequeo final de cada tipo, que son dos minutos por ejercicio.';
    r += '</p><button type="button" class="sim-btn sim-otro">Generar otro</button></div>';
    res.innerHTML = r;
    if (desplazar) irA(conId('fam2p-sim-resultado'));
  }

  function irA(el) {
    if (!el) return;
    const d = conId('fam2p-s11');
    if (d && !d.open) d.open = true;
    const y = el.getBoundingClientRect().top + window.pageYOffset - 70;
    window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
    try { el.focus({ preventScroll: true }); } catch (e) {}
  }

  // ---------- ir a una sección y volver ----------
  // Los enlaces "sección N" abren esa sección (y el apartado de adentro, si el destino está en
  // una sección cerrada), y queda un botón para volver al ejercicio o al resultado. Atrás
  // también vuelve ahí.
  function irASeccion(destinoId, desde) {
    const dest = conId(destinoId);
    if (!dest) return;
    const det = dest.tagName === 'DETAILS' ? dest : dest.closest('details');
    if (det) det.open = true;
    volverA = desde;
    try { history.pushState({ fam2pVolver: 1 }, '', '#' + destinoId); } catch (e) {}
    llevarA(dest);
    mostrarVolver();
  }
  // Salto sin animación, y una corrección un instante después por si algo cambió de alto
  // (la sección que se abrió, o el navegador restaurando la posición al volver con Atrás).
  function llevarA(el) {
    const y = () => Math.max(0, el.getBoundingClientRect().top + window.pageYOffset - 70);
    window.scrollTo(0, y());
    setTimeout(() => { if (Math.abs(el.getBoundingClientRect().top - 70) > 8) window.scrollTo(0, y()); }, 200);
  }
  function mostrarVolver() {
    if (!volver) {
      volver = document.createElement('button');
      volver.type = 'button';
      volver.className = 'sim-volver';
      volver.textContent = 'Volver al parcial';
      volver.addEventListener('click', () => {
        if (history.state && history.state.fam2pVolver) history.back();
        else regresar();
      });
      document.body.appendChild(volver);
    }
    volver.hidden = false;
    document.body.classList.add('fam2p-fijo-on');
  }
  function ocultarVolver() {
    if (volver) volver.hidden = true;
    volverA = null;
    if (!pastilla || pastilla.hidden) document.body.classList.remove('fam2p-fijo-on');
  }
  function regresar() {
    const a = volverA;
    ocultarVolver();
    const el = a && document.body.contains(a) ? a : a ? conId('fam2p-sim-cab') : null;
    if (!el) return;
    const d = conId('fam2p-s11');
    if (d) d.open = true;
    setTimeout(() => { llevarA(el); try { el.focus({ preventScroll: true }); } catch (e) {} }, 30);
  }

  // El resultado entra a "tus últimos" cuando están las cinco marcas; si después se cambia una,
  // se corrige esa misma entrada.
  function guardarPuntaje() {
    if (marcadas() < 5) return;
    const p = leerLista(K_PUNT).filter((x) => typeof x.p === 'number');
    const i = p.map((x) => x.f).indexOf(sim.creado);
    if (i !== -1) p[i].p = bien();
    else p.push({ p: bien(), f: sim.creado, modo: sim.modo });
    guardar(K_PUNT, p.slice(-5));
  }

  // ---------- acciones ----------
  function generar() {
    pararCrono();
    ocultarVolver();
    const r = document.querySelector('input[name="fam2p-sim-modo"]:checked');
    const modo = r && r.value === 'real' ? 'real' : 'nuevo';
    const hist = leerLista(K_HIST).filter(Array.isArray);
    let ids, esq, fecha = null, azar = false, esqElegido = false;
    if (modo === 'real') {
      const sel = conId('fam2p-sim-fecha');
      // "Generar otro" después de hacer una fecha elegida no repite la misma: pasa a una al azar.
      if (sel && sim && sim.modo === 'real' && sim.fase === 'corrigiendo' && sel.value === sim.fecha) sel.value = '';
      const clave = sel ? sel.value : '';
      azar = !clave;
      const x = elegirReal(clave, sim && sim.modo === 'real' ? sim.fecha : null);
      if (!x) return;
      ids = x.ids.slice();
      esq = x.esq;
      fecha = x.clave;
    } else {
      const sel = conId('fam2p-sim-esq');
      const op = sel ? sel.value : 'dos';
      esqElegido = /^[A-U]{5}$/.test(op);
      esq = esqueletoPara(op);
      ids = armarNuevo(esq, [].concat.apply([], hist.slice(-3)));
      if (!ids) return;
    }
    hist.push(ids);
    guardar(K_HIST, hist.slice(-3));
    sim = { v: 1, modo: modo, ids: ids, esq: esq, fecha: fecha, azar: azar, esqElegido: esqElegido, fase: 'resolviendo', vistos: {}, marcas: {}, creado: Date.now(), fin: null, resto: null };
    const chk = conId('fam2p-sim-crono-chk');
    if (chk && chk.checked) sim.fin = Date.now() + MINUTOS * 60000;
    persistir();
    pintarSimulacro();
    if (sim.fin) arrancarCrono();
    irA(conId('fam2p-sim-cab'));
  }

  function alGenerar(btn) {
    if (adoptarGuardado()) return;
    // Un toque de más justo después de generar no arma el descarte del parcial recién hecho.
    if (sim && Date.now() - sim.creado < 800) return;
    if (sim && (sim.fase === 'resolviendo' || marcadas() < 5) && !pedirConfirmacion(btn, 'gen', '¿Descartás el que estás haciendo? Tocá otra vez')) return;
    generar();
  }

  function terminar(porTiempo, desplazar) {
    if (!sim || sim.fase !== 'resolviendo') return;
    pararCrono();
    sim.fase = 'corrigiendo';
    sim.porTiempo = !!porTiempo;
    if (sim.modo === 'real') {
      const hechas = leerLista(K_REALES);
      if (hechas.indexOf(sim.fecha) === -1) { hechas.push(sim.fecha); guardar(K_REALES, hechas); }
    }
    persistir();
    pintarSimulacro();
    if (desplazar) irA(conId('fam2p-sim-cab'));
  }

  function alTerminar(btn) {
    if (!pedirConfirmacion(btn, 'fin', '¿Ya terminaste? Tocá otra vez para ver las resoluciones')) return;
    terminar(false, true);
  }

  // ---------- cronómetro ----------
  function asegurarPastilla() {
    if (pastilla) return pastilla;
    pastilla = document.createElement('button');
    pastilla.type = 'button';
    pastilla.className = 'sim-crono';
    pastilla.id = 'fam2p-sim-crono';
    pastilla.title = 'Ir al parcial';
    pastilla.hidden = true;
    pastilla.addEventListener('click', () => irA(conId('fam2p-sim-cab')));
    document.body.appendChild(pastilla);
    return pastilla;
  }
  function pararTic() { if (tic) { clearInterval(tic); tic = null; } }
  function pararCrono() {
    pararTic();
    if (pastilla) { pastilla.hidden = true; pastilla.classList.remove('sim-poco'); }
    if (!volver || volver.hidden) document.body.classList.remove('fam2p-fijo-on');
  }
  function arrancarCrono() {
    asegurarPastilla();
    pararTic();
    pastilla.hidden = false;
    document.body.classList.add('fam2p-fijo-on');
    latido();
    tic = setInterval(latido, 1000);
  }
  function latido() {
    if (adoptarGuardado()) return;
    if (!sim || !sim.fin || sim.fase !== 'resolviendo') { pararCrono(); return; }
    const r = sim.fin - Date.now();
    if (r <= 0) { terminarTiempo(true); return; }
    const hh = Math.floor(r / 3600000), mm = Math.floor((r % 3600000) / 60000), ss = Math.floor((r % 60000) / 1000);
    pastilla.innerHTML = '<span class="sim-crono-l">Quedan</span> <b>' + hh + ':' + dos(mm) + ':' + dos(ss) + '</b>';
    pastilla.setAttribute('aria-label', 'Quedan ' + (hh ? hh + (hh === 1 ? ' hora y ' : ' horas y ') : '') + mm + ' minutos. Ir al parcial');
    pastilla.classList.toggle('sim-poco', r < 10 * 60000);
  }
  function terminarTiempo(desplazar) {
    pararTic();
    if (!sim || sim.fase !== 'resolviendo') return;
    terminar(true, desplazar);
    asegurarPastilla();
    pastilla.innerHTML = '<b>Tiempo cumplido</b>';
    pastilla.setAttribute('aria-label', 'Tiempo cumplido: ya podés ver las resoluciones');
    pastilla.classList.add('sim-poco');
    pastilla.hidden = false;
    document.body.classList.add('fam2p-fijo-on');
    setTimeout(() => { if (pastilla && !tic) pararCrono(); }, 8000);
  }
  // Apagar el cronómetro con el parcial en curso lo pausa; al prenderlo sigue desde ahí.
  function alCambiarCrono(chk) {
    guardar(K_CRONO, chk.checked);
    adoptarGuardado();
    if (!sim || sim.fase !== 'resolviendo') return;
    if (chk.checked && !sim.fin) {
      sim.fin = Date.now() + (sim.resto > 0 ? sim.resto : MINUTOS * 60000);
      sim.resto = null;
      persistir();
      arrancarCrono();
    } else if (!chk.checked && sim.fin) {
      sim.resto = Math.max(0, sim.fin - Date.now());
      sim.fin = null;
      persistir();
      pararCrono();
    }
    pintarProgreso();
  }

  // ---------- arranque ----------
  function iniciar() {
    const raiz = conId('fam2p-sim');
    if (!raiz) return;
    const info = conId('fam2p-sim-info');
    if (!cargarBanco() || !EXAMENES.length) {
      if (info) info.textContent = 'No se pudo cargar el banco de ejercicios.';
      return;
    }
    const sel = conId('fam2p-sim-fecha');
    if (sel && sel.options.length < 2) {
      let grupo = null, g = null;
      EXAMENES.forEach((x) => {
        if (x.cuatri !== grupo) { grupo = x.cuatri; g = document.createElement('optgroup'); g.label = grupo; sel.appendChild(g); }
        const o = document.createElement('option');
        o.value = x.clave;
        o.textContent = x.clave;
        g.appendChild(o);
      });
    }
    if (info) {
      info.textContent = 'El banco tiene ' + BANCO.length + ' ejercicios reales y ' + EXAMENES.length + ' fechas completas. Las letras de los órdenes son los bloques del banco: A dominio, topología y conjuntos de nivel, H extremos libres, F función implícita, E regla de la cadena y composición, D plano tangente, recta normal y aproximación lineal, B curvas: recta tangente y plano normal, C límite, continuidad y diferenciabilidad, I extremos condicionados y absolutos.';
    }
    document.querySelectorAll('input[name="fam2p-sim-modo"]').forEach((x) => x.addEventListener('change', pintarModo));
    const chk = conId('fam2p-sim-crono-chk');
    if (chk) {
      chk.checked = !!leer(K_CRONO, false);
      chk.addEventListener('change', () => alCambiarCrono(chk));
    }
    const gen = conId('fam2p-sim-generar');
    if (gen) gen.addEventListener('click', () => alGenerar(gen));
    const out = conId('fam2p-sim-out');
    out.addEventListener('click', (ev) => {
      const t = ev.target;
      const a = t.closest('a[href^="#fam2p-s"]');
      if (a) {
        ev.preventDefault();
        irASeccion(a.getAttribute('href').slice(1), a.closest('.sim-e') || a.closest('.sim-caja'));
        return;
      }
      if (!sim) return;
      if (t.closest('button') && adoptarGuardado()) return;
      const ver = t.closest('.sim-ver');
      if (ver) {
        if (sim.fase !== 'corrigiendo') return;
        const box = ver.closest('.sim-e');
        sim.vistos[sim.ids[+box.dataset.k]] = true;
        abrir(box);
        persistir();
        const si = box.querySelector('.sim-marca-si');
        if (si) try { si.focus({ preventScroll: true }); } catch (err) {}
        return;
      }
      const m = t.closest('.sim-marca');
      if (m) {
        if (m.disabled || sim.fase !== 'corrigiendo') return;
        const box = m.closest('.sim-e');
        const antes = marcadas();
        sim.marcas[sim.ids[+box.dataset.k]] = m.dataset.v === '1';
        marcar(box, m.dataset.v === '1');
        persistir();
        guardarPuntaje();
        pintarProgreso();
        pintarPanel();
        pintarResultado(antes < 5 && marcadas() === 5);
        return;
      }
      const fin = t.closest('#fam2p-sim-terminar');
      if (fin) { alTerminar(fin); return; }
      if (t.closest('.sim-otro')) generar();
    });
    window.addEventListener('popstate', () => { if (volverA) regresar(); });
    window.addEventListener('storage', (e) => {
      if (e.key === K_ACTUAL || e.key === null) adoptarGuardado();
      if (e.key === K_PUNT || e.key === K_REALES || e.key === null) pintarPanel();
    });
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') adoptarGuardado(); });
    window.addEventListener('pageshow', (e) => { if (e.persisted) adoptarGuardado(); });

    const guardado = leer(K_ACTUAL, null);
    if (valido(guardado)) {
      sim = guardado;
      // El panel queda como se armó el parcial en pantalla.
      const radio = document.querySelector('input[name="fam2p-sim-modo"][value="' + (sim.modo === 'real' ? 'real' : 'nuevo') + '"]');
      if (radio) radio.checked = true;
      if (sim.modo === 'real' && !sim.azar && sel) sel.value = sim.fecha;
      const esqSel = conId('fam2p-sim-esq');
      if (sim.modo === 'nuevo' && sim.esqElegido && esqSel) esqSel.value = sim.esq;
      pintarModo();
      pintarSimulacro();
      // Un parcial a medio hacer se retoma a la vista, con la sección 10 abierta.
      if (sim.fase === 'resolviendo') { const d = conId('fam2p-s11'); if (d) d.open = true; }
      if (sim.fase === 'resolviendo' && sim.fin) {
        if (chk) chk.checked = true;
        if (Date.now() >= sim.fin) terminarTiempo(false); else arrancarCrono();
      }
    } else {
      pintarModo();
      pintarPanel();
    }
  }

  globalThis.SIM_ALG_P1 = { cargar: cargarBanco, armarNuevo: armarNuevo, esqueletoPara: esqueletoPara, elegirReal: elegirReal, BANCO: BANCO, EXAMENES: EXAMENES, RANGO: RANGO };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', iniciar);
  else iniciar();
})();
